INSERT INTO repo_esd_objectives (esd_objective_id, domain, objective_no, text, status) VALUES ('ESD_SDG04_SOC_01', 'Socio-emotional', '1', 'The learner is able to raise awareness of the importance of quality education for all, a humanistic and holistic approach to education, ESD and related approaches.', 'Active'), ('ESD_SDG04_SOC_02', 'Socio-emotional', '2', 'The learner is able through participatory methods to motivate and empower others to demand and use educational opportunities.', 'Active'), ('ESD_SDG04_SOC_03', 'Socio-emotional', '3', 'The learner is able to recognize the intrinsic value of education and to analyse and identify their own learning needs in their personal development.', 'Active'), ('ESD_SDG04_SOC_04', 'Socio-emotional', '4', 'The learner is able to recognize the importance of their own skills for improving their life, in particular for employment and entrepreneurship.', 'Active'), ('ESD_SDG04_SOC_05', 'Socio-emotional', '5', 'The learner is able to engage personally with ESD.', 'Active'), ('ESD_SDG04_BEH_01', 'Behavioural', '1', 'The learner is able to contribute to facilitating and implementing quality education for all, ESD and related approaches at different levels.', 'Active'), ('ESD_SDG04_BEH_02', 'Behavioural', '2', 'The learner is able to promote gender equality in education.', 'Active'), ('ESD_SDG04_BEH_03', 'Behavioural', '3', 'The learner is able to publicly demand and support the development of policies promoting free, equitable and quality education for all, ESD and related approaches as well as aiming at safe, accessible and inclusive educational facilities.', 'Active'), ('ESD_SDG04_BEH_04', 'Behavioural', '4', 'The learner is able to promote the empowerment of young people.', 'Active'), ('ESD_SDG04_BEH_05', 'Behavioural', '5', 'The learner is able to use all opportunities for their own education throughout their life, and to apply the acquired knowledge in everyday situations to promote sustainable development.', 'Active'), ('ESD_SDG05_COG_01', 'Cognitive', '1', 'The learner understands the concept of gender, gender equality and gender discrimination and knows about all forms of gender discrimination, violence and inequality (e.g. harmful practices such as female genital mutilation, honour killings and child marriage, unequal employment opportunities and pay, language construction, traditional gender roles, gendered impact of natural hazards) and understands the current and historical causes of gender inequality.', 'Active'), ('ESD_SDG05_COG_02', 'Cognitive', '2', 'The learner understands the basic rights of women and girls, including their right to freedom from exploitation and violence and their reproductive rights.', 'Active'), ('ESD_SDG05_COG_03', 'Cognitive', '3', 'The learner understands levels of gender equality within their own country and culture in comparison to global norms (while respecting cultural sensitivity), including the intersectionality of gender with other social categories such as ability, religion and race.', 'Active'), ('ESD_SDG05_COG_04', 'Cognitive', '4', 'The learner knows the opportunities and benefits provided by full gender equality and participation in legislation and governance, including public budget allocation, the labour market and public and private decision-making.', 'Active'), ('ESD_SDG05_COG_05', 'Cognitive', '5', 'The learner understands the role of education, enabling technology and legislation in empowering and ensuring the full participation of all genders.', 'Active'), ('ESD_SDG05_SOC_01', 'Socio-emotional', '1', 'The learner is able to recognize and question traditional perception of gender roles in a critical approach, while respecting cultural sensitivity.', 'Active'), ('ESD_SDG05_SOC_02', 'Socio-emotional', '2', 'The learner is able to identify and speak up against all forms of gender discrimination and debate the benefits of full empowerment of all genders.', 'Active'), ('ESD_SDG05_SOC_03', 'Socio-emotional', '3', 'The learner is able to connect with others who work to end gender discrimination and violence, empower those who may still be disempowered and promote respect and full equality on all levels.', 'Active'), ('ESD_SDG05_SOC_04', 'Socio-emotional', '4', 'The learner is able to reflect on their own gender identity and gender roles.', 'Active'), ('ESD_SDG05_SOC_05', 'Socio-emotional', '5', 'The learner is able to feel empathy and solidarity with those who differ from personal or community gender expectations and roles.', 'Active'), ('ESD_SDG05_BEH_01', 'Behavioural', '1', 'The learner is able to take the measure of their surroundings to empower themselves or others who are discriminated against because of their gender.', 'Active'), ('ESD_SDG05_BEH_02', 'Behavioural', '2', 'The learner is able to evaluate, participate in and influence decision-making about gender equality and participation.', 'Active'), ('ESD_SDG05_BEH_03', 'Behavioural', '3', 'The learner is able to support others in developing empathy across genders and breaking down gender discrimination and violence.', 'Active'), ('ESD_SDG05_BEH_04', 'Behavioural', '4', 'The learner is able to observe and identify gender discrimination.', 'Active'), ('ESD_SDG05_BEH_05', 'Behavioural', '5', 'The learner is able to plan, implement, support and evaluate strategies for gender equality.', 'Active'), ('ESD_SDG06_COG_01', 'Cognitive', '1', 'The learner understands water as a fundamental condition of life itself, the importance of water quality and quantity, and the causes, effects and consequences of water pollution and water scarcity.', 'Active'), ('ESD_SDG06_COG_02', 'Cognitive', '2', 'The learner understands that water is part of many different complex global interrelationships and systems.', 'Active'), ('ESD_SDG06_COG_03', 'Cognitive', '3', 'The learner knows about the global unequal distribution of access to safe drinking water and sanitation facilities.', 'Active'), ('ESD_SDG06_COG_04', 'Cognitive', '4', 'The learner understands the concept of “virtual water”.', 'Active'), ('ESD_SDG06_COG_05', 'Cognitive', '5', 'The learner understands the concept of Integrated Water Resources Management (IWRM) and other strategies for ensuring the availability and sustainable management of water and sanitation, including flood and drought risk management.', 'Active'), ('ESD_SDG06_SOC_01', 'Socio-emotional', '1', 'The learner is able to participate in activities of improving water and sanitation management in local communities.', 'Active'), ('ESD_SDG06_SOC_02', 'Socio-emotional', '2', 'The learner is able to communicate about water pollution, water access and water saving measures and to create visibility about success stories.', 'Active'), ('ESD_SDG06_SOC_03', 'Socio-emotional', '3', 'The learner is able to feel responsible for their water use.', 'Active'), ('ESD_SDG06_SOC_04', 'Socio-emotional', '4', 'The learner is able to see the value in good sanitation and hygiene standards.', 'Active'), ('ESD_SDG06_SOC_05', 'Socio-emotional', '5', 'The learner is able to question socio-economic differences as well as gender disparities in the access to safe drinking water and sanitation facilities.', 'Active'), ('ESD_SDG06_BEH_01', 'Behavioural', '1', 'The learner is able to cooperate with local authorities in the improvement of local capacity for self-sufficiency.', 'Active'), ('ESD_SDG06_BEH_02', 'Behavioural', '2', 'The learner is able to contribute to water resources management at the local level.', 'Active'), ('ESD_SDG06_BEH_03', 'Behavioural', '3', 'The learner is able to reduce their individual water footprint and to save water practicing their daily habits.', 'Active'), ('ESD_SDG06_BEH_04', 'Behavioural', '4', 'The learner is able to plan, implement, evaluate and replicate activities that contribute to increasing water quality and safety.', 'Active'), ('ESD_SDG06_BEH_05', 'Behavioural', '5', 'The learner is able to evaluate, participate in and influence decision-making on management strategies of local, national and international enterprises related to water pollution.', 'Active'), ('ESD_SDG07_COG_01', 'Cognitive', '1', 'The learner knows about different energy resources – renewable and non-renewable – and their respective advantages and disadvantages including environmental impacts, health issues, usage, safety and energy security, and their share in the energy mix at the local, national and global level.', 'Active'), ('ESD_SDG07_COG_02', 'Cognitive', '2', 'The learner knows what energy is primarily used for in different regions of the world.', 'Active'), ('ESD_SDG07_COG_03', 'Cognitive', '3', 'The learner understands the concept of energy efficiency and sufficiency and knows socio-technical strategies and policies to achieve efficiency and sufficiency.', 'Active'), ('ESD_SDG07_COG_04', 'Cognitive', '4', 'The learner understands how policies can influence the development of energy production, supply, demand and usage.', 'Active'), ('ESD_SDG07_COG_05', 'Cognitive', '5', 'The learner knows about harmful impacts of unsustainable energy production, understands how renewable energy technologies can help to drive sustainable development and understands the need for new and innovative technologies and especially technology transfer in collaborations between countries.', 'Active'), ('ESD_SDG07_SOC_01', 'Socio-emotional', '1', 'The learner is able to communicate the need for energy efficiency and sufficiency.', 'Active'), ('ESD_SDG07_SOC_02', 'Socio-emotional', '2', 'The learner is able to assess and understand the need for affordable, reliable, sustainable and clean energy of other people/other countries or regions.', 'Active'), ('ESD_SDG07_SOC_03', 'Socio-emotional', '3', 'The learner is able to cooperate and collaborate with others to transfer and adapt energy technologies to different contexts and to share energy best practices of their communities.', 'Active'), ('ESD_SDG07_SOC_04', 'Socio-emotional', '4', 'The learner is able to clarify personal norms and values related to energy production and usage as well as to reflect and evaluate their own energy usage in terms of efficiency and sufficiency.', 'Active'), ('ESD_SDG07_SOC_05', 'Socio-emotional', '5', 'The learner is able to develop a vision of a reliable, sustainable energy production, supply and usage in their country.', 'Active') ON CONFLICT DO NOTHING;